package repository
import("context";"fmt";"github.com/google/uuid";"github.com/jackc/pgx/v5";"github.com/openoms-org/openoms/apps/api-server/internal/model")
func(r *MarketplaceSKUMappingRepository)ListByCanonical(ctx context.Context,tx pgx.Tx,productID uuid.UUID,variantID *uuid.UUID)([]model.MarketplaceSKUMapping,error){q:="SELECT id,tenant_id,integration_id,product_id,variant_id,provider,external_item_id,external_model_id,external_sku,mapping_source,active,created_at,updated_at FROM marketplace_sku_mappings WHERE product_id=$1 AND active=true";args:=[]any{productID};if variantID!=nil{q+=" AND variant_id=$2";args=append(args,*variantID)}else{q+=" AND variant_id IS NULL"};rows,err:=tx.Query(ctx,q,args...);if err!=nil{return nil,fmt.Errorf("list marketplace sku mappings: %w",err)};defer rows.Close();var out []model.MarketplaceSKUMapping;for rows.Next(){var m model.MarketplaceSKUMapping;if err:=rows.Scan(&m.ID,&m.TenantID,&m.IntegrationID,&m.ProductID,&m.VariantID,&m.Provider,&m.ExternalItemID,&m.ExternalModelID,&m.ExternalSKU,&m.MappingSource,&m.Active,&m.CreatedAt,&m.UpdatedAt);err!=nil{return nil,err};out=append(out,m)};return out,rows.Err()}
